\title{The Kakeya Problem in the Finite-Field Model:\\
Bush Counts, Incidences, and Sumset Growth}
\author{Aristotle}
\date{2026-06-27}

\begin{document}
\maketitle

\begin{abstract}
The Kakeya conjecture asserts that a Besicovitch set in $\R^n$ --- a set
containing a unit line segment in every direction --- has Hausdorff dimension
$n$. The conjecture is known in the plane (Davies's theorem, dimension $2$) and
partially in three dimensions (Wolff's bound, dimension $\geq 5/2$), and is
deeply entangled with restriction estimates for the Fourier transform and with
additive combinatorics via the Katz--Tao framework. We develop and state with
full precision a rigorously verified fragment of the \emph{finite-field model}
of the Kakeya problem. Working in the plane $F^2$ over a finite field $F$ with
$q$ elements, we prove: (i) the \emph{bush} of all $q$ lines through the origin
has exactly $q^2-q+1$ points; (ii) two lines of distinct slope through the
origin meet in exactly one point; (iii) any through-origin Kakeya set has at
least $q^2-q+1$ points. On the additive side, we prove the iterated-sumset
growth law $|kA|\geq\min(p,\,k(|A|-1)+1)$ for nonempty $A\subseteq\Z/p$ ($p$
prime) by induction from Cauchy--Davenport, with the saturation corollary that
$|A|\geq 2$ implies $kA=\Z/p$ once $k\geq p-1$. We give proof sketches,
algorithms, numerical evidence, and a discussion of how these exact fragments
map onto the broader Kakeya program.
\end{abstract}

\section{Introduction}

\subsection{The continuous problem}
In 1917 So\=ichi Kakeya asked for the minimal area of a planar region inside
which a unit segment can be continuously rotated through all directions.
Besicovitch (1928) showed the area can be made arbitrarily small. A
\emph{Besicovitch set} (or \emph{Kakeya set}) is a set $K\subseteq\R^n$
containing a unit segment in every direction; such sets can have measure zero.

The \emph{Kakeya conjecture} sharpens the question from measure to dimension:
every Besicovitch set in $\R^n$ has Hausdorff dimension $n$. Known cases:
\begin{itemize}
  \item $n=2$ (Davies, 1971): dimension exactly $2$.
  \item $n=3$ (Wolff, 1995): dimension at least $5/2$.
  \item general $n$: open.
\end{itemize}
Via the restriction conjecture the problem governs Fourier concentration; via
the Katz--Tao framework, dimension bounds reduce to sum--difference estimates in
additive combinatorics.

\subsection{The finite-field model}
Wolff proposed replacing $\R^n$ by $F^n$ for a finite field $F$ with $q$
elements. A Kakeya set in $F^n$ contains a full line in every direction;
``dimension'' becomes the exponent $\alpha$ in $|K|\gtrsim q^{\alpha}$. Dvir
(2008) resolved the finite-field conjecture, $|K|\gtrsim_n q^n$, by the
polynomial method. We isolate the cleanest exactly-provable fragments of this
model.

\subsection{Contributions}
\begin{enumerate}
  \item An exact bush count $|B|=q^2-q+1$ (Theorem~\ref{thm:bushcard}).
  \item The one-point incidence lemma (Theorem~\ref{thm:incidence}).
  \item The discrete Kakeya lower bound (Theorem~\ref{thm:kakeya}).
  \item The iterated-sumset growth law (Theorem~\ref{thm:growth}) and the
  saturation corollary (Theorem~\ref{thm:sat}).
\end{enumerate}

\section{Preliminaries and Definitions}

Throughout, $F$ is a finite field with $q=|F|$ elements (the smallest has
$q=2$); $F^2$ is the affine plane with $q^2$ points. For the additive results
$p$ is prime and $\Z/p=\F_p$.

\begin{definition}[Line through the origin]
For $m\in F$, set $L_m=\{(x,m\cdot x):x\in F\}\subseteq F^2$. Each $L_m$ has $q$
points and contains $(0,0)$.
\end{definition}

\begin{definition}[Bush]
$B=\bigcup_{m\in F}L_m\subseteq F^2$.
\end{definition}

\begin{definition}[Kakeya set, through-origin model]
$K\subseteq F^2$ is a \emph{Kakeya set} if $L_m\subseteq K$ for all $m\in F$.
\end{definition}

\begin{definition}[Iterated sumset]
For $A,B\subseteq\Z/p$, $A+B=\{a+b:a\in A,\,b\in B\}$. Define $0A=\{0\}$ and
$(k{+}1)A=A+kA$, so $1A=A$ and $kA=\underbrace{A+\cdots+A}_{k}$.
\end{definition}

\begin{theorem}[Cauchy--Davenport]\label{thm:cd}
For nonempty $A,B\subseteq\Z/p$ with $p$ prime,
$|A+B|\geq\min\!\big(p,\,|A|+|B|-1\big)$.
\end{theorem}

\section{The Bush in $F^2$}

\begin{theorem}[Bush characterization]\label{thm:bushchar}
$B=\{(a,b)\in F^2:a\neq 0\}\cup\{(0,0)\}$.
\end{theorem}
\begin{proof}[Proof sketch]
($\subseteq$) A point of $B$ is $(x,mx)$; if $x=0$ it is $(0,0)$, else $x\neq0$.
($\supseteq$) The origin lies on $L_0$; for $(a,b)$ with $a\neq0$, set
$m=b/a$ (valid in a field) so $(a,b)\in L_m$. The key step is solving $m=b/a$,
using multiplicative inverses.
\end{proof}

\begin{lemma}[Bad set count]\label{lem:badcard}
The off-origin vertical axis $\Bad=\{(0,b):b\neq0\}$ has $q-1$ points.
\end{lemma}
\begin{proof}[Proof sketch]
$b\mapsto(0,b)$ is a bijection from $F\setminus\{0\}$ (size $q-1$) onto $\Bad$.
\end{proof}

\begin{theorem}[Bush count]\label{thm:bushcard}
$|B|=q^2-q+1$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:bushchar}, $\Bad$ is the complement of $B$, so
$|B|=|F^2|-|\Bad|=q^2-(q-1)=q^2-q+1$ by Lemma~\ref{lem:badcard}. The
natural-number arithmetic is exact for all $q\geq1$.
\end{proof}

The bush occupies a fraction $1-\tfrac1q+\tfrac1{q^2}\to1$ of the plane.

\begin{theorem}[Incidence lemma]\label{thm:incidence}
If $m_1\neq m_2$ then $L_{m_1}\cap L_{m_2}=\{(0,0)\}$.
\end{theorem}
\begin{proof}[Proof sketch]
A common point $(x,y)$ has $m_1x=y=m_2x$, so $(m_1-m_2)x=0$; as the field has no
zero divisors and $m_1\neq m_2$, $x=0$ and $y=0$. Conversely $(0,0)$ is on every
line.
\end{proof}

\begin{theorem}[Kakeya lower bound]\label{thm:kakeya}
Every Kakeya set $K\subseteq F^2$ satisfies $|K|\geq q^2-q+1$.
\end{theorem}
\begin{proof}[Proof sketch]
$L_m\subseteq K$ for all $m$ gives $B=\bigcup_m L_m\subseteq K$, so
$|K|\geq|B|=q^2-q+1$ by Theorem~\ref{thm:bushcard}.
\end{proof}

\section{The Additive Bridge: Sumset Growth in $\Z/p$}

\begin{lemma}[Nonemptiness]\label{lem:nonempty}
If $A\neq\emptyset$ then $kA\neq\emptyset$ for all $k$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction on $k$: $0A=\{0\}$; a sumset of nonempty sets is nonempty.
\end{proof}

\begin{theorem}[Iterated sumset growth]\label{thm:growth}
For nonempty $A\subseteq\Z/p$ ($p$ prime) and all $k\geq0$,
\[
  |kA|\geq\min\!\big(p,\,k(|A|-1)+1\big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $k$. Base: $|0A|=1=\min(p,1)$. Step: by Theorem~\ref{thm:cd},
$|(k{+}1)A|=|A+kA|\geq\min(p,|A|+|kA|-1)$. If $|kA|\geq p$ both sides cap at $p$;
otherwise substitute $|kA|\geq k(|A|-1)+1$ to get
$|A|+|kA|-1\geq(k{+}1)(|A|-1)+1$, and take $\min$ with $p$.
\end{proof}

\noindent\textbf{Sharpness.} For $A=\{0,1,\dots,m-1\}$ one has
$kA=\{0,\dots,k(m-1)\}$ of size $k(m-1)+1$ while $<p$; arithmetic progressions
are extremal, with saturation at $k=\lceil(p-1)/(|A|-1)\rceil$.

\begin{theorem}[Saturation]\label{thm:sat}
If $|A|\geq2$ then $kA=\Z/p$ for all $k\geq p-1$.
\end{theorem}
\begin{proof}[Proof sketch]
$|A|-1\geq1$, so for $k\geq p-1$, $k(|A|-1)+1\geq p$; then
Theorem~\ref{thm:growth} gives $|kA|\geq p$, hence $kA=\Z/p$. The hypothesis is
necessary: a singleton stays a singleton, matching $\min(p,1)=1$.
\end{proof}

\section{Algorithms and Numerical Evidence}

\begin{itemize}
  \item \textbf{Bush enumeration:} build $L_m$ per slope, union; verify
  $|B|=q^2-q+1$ and that the complement is the $q-1$ off-origin axis points.
  Cost $O(q^2)$.
  \item \textbf{Pairwise incidence:} for all $m_1\neq m_2$ verify
  $L_{m_1}\cap L_{m_2}=\{(0,0)\}$. Cost $O(q^3)$.
  \item \textbf{Sumset growth:} compute $kA$ by repeated modular addition and
  compare $|kA|$ to $\min(p,k(|A|-1)+1)$. Cost $O(p|A|)$ per step.
\end{itemize}

Representative bush counts ($q^2-q+1$): $q=2\!\to\!3$, $q=3\!\to\!7$,
$q=5\!\to\!21$, $q=7\!\to\!43$, $q=11\!\to\!111$. For $A=\{0,1,2\}\subseteq\Z/11$
the sizes $|kA|$ are $3,5,7,9,11,11,\dots$, matching $\min(11,2k+1)$ and
saturating at $k=5$.

\section{Applications and Connections}
Kakeya lower bounds feed restriction/Bochner--Riesz estimates for the Fourier
transform; the Katz--Tao reduction turns sum--difference growth
(Theorem~\ref{thm:growth}) plus incidence counting
(Theorem~\ref{thm:incidence}) into geometric size bounds; and the line API of
Section~3 is the substrate for Dvir's polynomial method.

\section{Future Work}
\begin{enumerate}
  \item Sharp 2D bound $q(q+1)/2$ over all $q+1$ affine directions via a
  Bonferroni inequality with the incidence lemma supplying the pairwise term.
  \item Dvir's bound $\binom{q+n-1}{n}\geq q^n/n!$ in $F_q^n$ via a vanishing
  low-degree polynomial.
  \item Exact saturation threshold $\lceil(p-1)/(|A|-1)\rceil$, optimal among
  all seeds of given size.
  \item Katz--Tao sum--difference $\Rightarrow$ discrete dimension bound,
  upgrading $q^{3/2}$ toward Wolff's $5/2$ in $F_q^3$.
\end{enumerate}

\section{Conclusion}
In the finite-field model the Kakeya problem yields exact answers: the bush has
precisely $q^2-q+1$ points, distinct directions cross once, every Kakeya set
inherits the full bush, and sumsets in $\Z/p$ grow at the sharp rate
$\min(p,\,k(|A|-1)+1)$ until they fill the group --- a self-contained miniature
of the geometry and arithmetic behind the full conjecture.

